INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Muss ich hier immer allein programmieren?', 2, '[{"text": "Nein", "correct": true, "because": "Pair-Programming üblich"}, {"text": "Ja", "correct": false, "because": "Zusammenarbeit gefördert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technik nutze ich, um Tests zuerst zu schreiben?', 3, '[{"text": "Test-Driven Development", "correct": true, "because": "Tests vor Code"}, {"text": "Pair-Programming", "correct": false, "because": "Zusammenarbeit"}, {"text": "Häufige Releases", "correct": false, "because": "Auslieferung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Praktiken fördern hier die Code-Qualität?', 5, '[{"text": "Pair-Programming", "correct": true, "because": "Doppelte Überprüfung"}, {"text": "Test-Driven Development", "correct": true, "because": "Fehler früh erkennen"}, {"text": "Seltenes Testen", "correct": false, "because": "Tests zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Pair-Programming ist zu zweit. b) Releases sind selten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Releases häufig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei diesen Praktiken?', 4, '[{"text": "Tests vor Code", "correct": false, "because": "TDD-Kern"}, {"text": "Zusammenarbeit", "correct": false, "because": "Pair-Programming"}, {"text": "Einmalige Lieferung", "correct": true, "because": "Häufige Releases"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ich hier selten teste?', 2, '[{"text": "Nein", "correct": true, "because": "TDD erfordert viele Tests"}, {"text": "Ja", "correct": false, "because": "Tests zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich für direkte Teamarbeit?', 3, '[{"text": "Pair-Programming", "correct": true, "because": "Zwei Entwickler"}, {"text": "Test-Driven Development", "correct": false, "because": "Tests fokus"}, {"text": "Häufige Releases", "correct": false, "because": "Auslieferung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringen diese Techniken?', 5, '[{"text": "Bessere Code-Qualität", "correct": true, "because": "TDD und Pairing"}, {"text": "Schnelles Feedback", "correct": true, "because": "Häufige Releases"}, {"text": "Lange Wartezeiten", "correct": false, "because": "Releases oft"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) TDD schreibt Tests zuerst. b) Pairing ist optional. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Pairing ist Praxis"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich hier nicht unbedingt?', 4, '[{"text": "Tests vorab", "correct": false, "because": "TDD-Grundlage"}, {"text": "Teamarbeit", "correct": false, "because": "Pair-Programming"}, {"text": "Seltenes Ausliefern", "correct": true, "because": "Häufige Releases"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Releases hier selten?', 2, '[{"text": "Nein", "correct": true, "because": "Häufige Releases Praxis"}, {"text": "Ja", "correct": false, "because": "Regelmäßige Lieferung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ansätze sichern hier schnelle Ergebnisse?', 4, '[{"text": "Häufige Releases", "correct": true, "because": "Schnelles Feedback"}, {"text": "Pair-Programming", "correct": true, "because": "Effiziente Entwicklung"}, {"text": "Einmalige Tests", "correct": false, "because": "TDD zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ich hier allein arbeite. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Pair-Programming üblich"}, {"text": "Ja", "correct": false, "because": "Zusammenarbeit gefördert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Entwicklung?', 3, '[{"text": "Tests schreiben", "correct": true, "because": "TDD als Basis"}, {"text": "Code ohne Tests", "correct": false, "because": "TDD erfordert Tests"}, {"text": "Seltenes Liefern", "correct": false, "because": "Häufige Releases"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Pairing fördert Qualität. b) Tests kommen nach dem Code.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Tests vor Code"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Stärken haben diese Praktiken?', 5, '[{"text": "Fehlerreduktion", "correct": true, "because": "TDD und Pairing"}, {"text": "Schnelle Anpassung", "correct": true, "because": "Häufige Releases"}, {"text": "Lange Zyklen", "correct": false, "because": "Kurze Releases"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist hier unwichtig?', 3, '[{"text": "Pair-Programming", "correct": false, "because": "Fördert Qualität"}, {"text": "TDD", "correct": false, "because": "Sichert Code"}, {"text": "Einzelarbeit", "correct": true, "because": "Teamarbeit zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Teste ich hier nach dem Code?', 3, '[{"text": "Nein", "correct": true, "because": "TDD schreibt Tests zuerst"}, {"text": "Ja", "correct": false, "because": "Tests vorab"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ich hier selten liefere?', 2, '[{"text": "Nein", "correct": true, "because": "Häufige Releases Praxis"}, {"text": "Ja", "correct": false, "because": "Regelmäßige Auslieferung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Praxis wähle ich für besseren Code?', 4, '[{"text": "Test-Driven Development", "correct": true, "because": "Tests sichern Qualität"}, {"text": "Seltenes Testen", "correct": false, "because": "TDD zentral"}, {"text": "Einzelcoding", "correct": false, "because": "Pairing üblich"}]');
